INSERT INTO capacite (id, classe_id, specialite_id, niveau, nature, ligne, rang, nom, nom_cle, type, type_brut, limite_nombre, limite_periode, effet, origine, source_ref, remarque) VALUES ('capacites/mage-soin-etrange', 'classes/mage', 'classes/mage#specialite:mage-blanc', 10, 'choix', 29, 1, 'Soin étrange', 'soin-etrange', 'passif', 'Passif', NULL, NULL, 'Le sort d''attaque basique niveau 1* devient un soin quand il est utilisé sur un allié.', 'classes', 'Classe Maverick V7 › Mage › X29:AC34', 'Il est capable de soigner aussi les morts vivants.
INSERT INTO capacite (id, classe_id, specialite_id, niveau, nature, ligne, rang, nom, nom_cle, type, type_brut, limite_nombre, limite_periode, effet, origine, source_ref, remarque) VALUES ('capacites/mage-soin-similaire', 'classes/mage', 'classes/mage#specialite:mage-blanc', 20, 'choix', 43, 2, 'Soin similaire', 'soin-similaire', 'passif', 'Passif', NULL, NULL, 'Le lanceur de soin récupère autant de pv qu''il rend à un allié (sauf à lui-même).', 'classes', 'Classe Maverick V7 › Mage › AE43:AJ48', 'Si jamais le lanceur est un mort vivant et qu''il soigne via la magie de la lumière, il récupère quand même la santé qu''il soigne.');
INSERT INTO capacite (id, classe_id, specialite_id, niveau, nature, ligne, rang, nom, nom_cle, type, type_brut, limite_nombre, limite_periode, effet, origine, source_ref, remarque) VALUES ('capacites/mage-toujours-plus', 'classes/mage', 'classes/mage#specialite:mage-noir', 20, 'choix', 43, 1, 'Toujours plus', 'toujours-plus', 'actif', 'Actif (2 fois/combat)', 2, 'combat', 'Peut lancer deux sorts d''attaque ou/et d''entrave en 1 seul tour. Il est nécessaire de réussir un jet de concentration entre les deux sorts.', 'classes', 'Classe Maverick V7 › Mage › A43:F48', 'Bien entendu qu''on parle des sorts qui sont non IC. Le deuxième sort crame un IC sur les 3 disponibles dans le tour donc prudence à en avoir un avant d''utiliser cette capacité.
